class GSLVector:
    _lib = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    _lib2 = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    def __init__(self, data):
        self.data = (ctypes.c_double * len(data))(*data)
        self.size = len(data)

    def __del__(self):
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so").cblas_daxpy(self.size, 1.0, self.data, 1, ctypes.pointer(ctypes.c_double(0)))

    def __add__(self, other):
        if not isinstance(other, GSLVector):
            return GSLVector(self.data + other)
        result = GSLVector([0.0]*self.size)

        # Call the vector_add function from GSL
        self._lib.vector_add.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
        self._lib.vector_add.restype = ctypes.c_int

        # Ensure the function is properly called
        self._lib.vector_add(self.data, other.data, result.data)

        return result

