import ctypes

class GSLMatrix(ctypes.Structure):
    _fields_ = [
        ('data', ctypes.POINTER(ctypes.c_double)),
        ('rows', ctypes.c_size_t),
        ('cols', ctypes.c_size_t)
    ]

def create_gsl_matrix(np_array):
    mat = GSLMatrix()
    mat.rows = np_array.shape[0]
    mat.cols = np_array.shape[1]
    mat.data = ctypes.pointer(np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double)))
    return mat

def copy_matrix(dest, src):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl.gsl_matrix_memcpy.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_matrix_memcpy.restype = ctypes.c_int
    return gsl.gsl_matrix_memcpy(dest.data, src.data)

def copy_matrix_wrapper(dest, src):
    if dest.rows != src.rows or dest.cols != src.cols:
        return -1
    return copy_matrix(dest, src)"}

