import ctypes
import sys

class GSLMatrix(ctypes.Structure):
    _fields_ = []

def gsl_matrix_alloc(rows, cols):
    return ctypes.pointer(ctypes_malloc(rows * cols * ctypes.sizeof(ctypes.c_double)))

def gsl_matrix_free(matrix):
    ctypes.free(matrix)

def numpy_to_gsl_matrix(np_array):
    gsl_matrix = gsl_matrix_alloc(np_array.shape[0], np_array.shape[1])
    for i in range(np_array.shape[0]):
        for j in range(np_array.shape[1]):
            gsl_matrix.contents.data[i * np_array.shape[1] + j] = np_array[i, j]
    return gsl_matrix

def gsl_matrix_to_numpy(matrix):
    np_array = np.zeros((matrix.contents.rows, matrix.contents.cols), dtype=np.float64)
    for i in range(matrix.contents.rows):
        for j in range(matrix.contents.cols):
            np_array[i, j] = matrix.contents.data[i * matrix.contents.cols + j]
    return np_array

