def compute_covariance(jacobian, epsrel):
    # Validate input
    if not isinstance(jacobian, np.ndarray):
        raise ValueError("Jacobian must be a numpy array")
    if jacobian.ndim != 2:
        raise ValueError("Jacobian must be a 2D array")
    if jacobian.shape[0] == 0 or jacobian.shape[1] == 0:
        raise ValueError("Jacobian dimensions must be positive")

    # Convert Jacobian to GSL matrix
    gsl_jacobian = numpy_to_gsl_matrix(jacobian)

    # Compute covariance matrix
    gsl_covar = gsl.gsl_multifit_covar(gsl_jacobian, epsrel)

    # Convert covariance matrix to numpy array
    cov_matrix = gsl_matrix_to_numpy(gsl_covar)

    # Free GSL matrices
    gsl_matrix_free(gsl_jacobian)
    gsl_matrix_free(gsl_covar)

    return cov_matrix

