    def init_lib(cls):
        if cls._lib is None:
            cls._lib = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
            cls._lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    @classmethod
    def create_gsl_vector(cls, data):
        cls.init_lib()
        size = len(data)
        vec = cls._lib.gsl_vector_alloc(size)
        vec = ctypes.c_void_p(vec)

        for i in range(size):
            cls._lib.gsl_vector_set(vec, i, data[i])
        return vec

    @classmethod
    def gsl_vector_memcpy(cls, src, dest):
        cls.init_lib()
        cls._lib.gsl_vector_memcpy(src, dest)

    @classmethod
    def gsl_vector_free(cls, vec):
        cls.init_lib()
        cls._lib.gsl_vector_free(vec)

