gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class gsl_function(ctypes.Structure):
    _fields_ = [('function', ctypes.POINTER(ctypes.CFUNGCP)), ('params', ctypes.POINTER(ctypes.c_double))]

class gsl_integration_qaws_table(ctypes.Structure):
    _fields_ = []

class gsl_integration_workspace(ctypes.Structure):
    _fields_ = []

def create_workspace(limit):
    return gsl.gsl_integration_workspace_alloc_qaws(limit)

def create_qaws_table():
    return gsl.gsl_integration_qaws_table_alloc()

def free_workspace(workspace):
    gsl.gsl_integration_workspace_free(workspace)

def free_qaws_table(table):
    gsl.gsl_integration_qaws_table_free(table)

def my_function(x):
    return np.sin(x)

def compute_integral(f, a, b, table, epsabs, epsrel, limit, workspace):
    f_c = gsl_function()
    f_c.function = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(f)
    f_c.params = ctypes.pointer(ctypes.c_double(0))

    result = gsl.gsl_integration_qaws(f_c, a, b, table, epsabs, epsrel, limit, workspace)

    return result

if __name__ == "__main__":
    table = create_qaws_table()
    workspace = create_workspace(100)
    f = my_function
    a = 0.0
    b = np.pi
    epsabs = 1e-5
    epsrel = 1e-5
    limit = 100

    result = compute_integral(f, a, b, table, epsabs, epsrel, limit, workspace)

    assert abs(result - np.sin(b) + np.sin(a)) < 1e-4
    assert abs(result - np.sin(b) + np.sin(a)) < 1e-4

    print(f"Integral result: {result}")
    print(f"Estimated absolute error: {result}")

    free_workspace(workspace)
    free_qaws_table(table)

