        gsl.gsl_blas_dsymm_3 = ctypes.CFUNCTYPE(ctypes.c_int)("gsl_blas_dsymm_3")
        gsl.gsl_blas_dsymm_2 = ctypes.CFUNCTYPE(ctypes.c_int)("gsl_blas_dsymm_2")

        # Check if matrix is symmetric
        for i in range(self.size):
            for j in range(i + 1, self.size):
                if abs(self.matrix[i*self.size + j] - self.matrix[j*self.size + i]) > 1e-8:
                    return False

        # Check if matrix is positive definite
        # Use Cholesky decomposition to check
        try:
            chol = GSLMatrix(np.eye(self.size))
            gsl.gsl_linalg_cholesky_decomp(ctypes.pointer(chol.matrix), ctypes.pointer(ctypes.c_int(self.size)))
            return True
        except:
            return False

