        # Load GSL libraries
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Define function prototypes
        gsl.gsl_linalg_cholesky_decomp = ctypes.CFUNCTYPE(None)("gsl_linalg_cholesky_decomp")

        # Create lower triangular matrix
        lower = GSLMatrix(np.zeros((self.size, self.size)))
        gsl.gsl_linalg_cholesky_decomp(ctypes.pointer(lower.matrix), ctypes.pointer(ctypes.c_int(self.size)))

        # Fill the lower triangular part
        for i in range(self.size):
